def proof_ball(adj, initial, max_steps):
    balls = [set(initial)]
    for k in range(1, max_steps + 1):
        prev = balls[-1]
        neighbors = set()
        for v in prev:
            neighbors.update(adj.get(v, set()))
        new_ball = prev | neighbors
        balls.append(new_ball)
        if new_ball == prev:
            while len(balls) <= max_steps:
                balls.append(new_ball)
            break
    return balls

import math
def proof_length_lower_bound(n, s, conductance):
    if conductance <= 0 or s <= 0 or n <= 2 * s:
        return 0.0
    return math.log(n / (2 * s)) / math.log(1 + conductance)
